select 'ledger_row_count' k, (select count(*)::text from supabase_migrations.schema_migrations where version='20260924120000') v
union all select 'ledger_total', (select count(*)::text from supabase_migrations.schema_migrations)
union all select 'ledger_max', (select max(version) from supabase_migrations.schema_migrations)
union all select 'a3_defn_md5', md5(pg_get_functiondef('public.record_payout_attempt_result(uuid,text,text,jsonb)'::regprocedure))
union all select 'a3_prosrc_md5', (select md5(prosrc) from pg_proc where oid='public.record_payout_attempt_result(uuid,text,text,jsonb)'::regprocedure)
union all select 'a4_defn_md5', md5(pg_get_functiondef('public.flag_payout_reversal_required(uuid,text,jsonb)'::regprocedure))
union all select 'a4_prosrc_md5', (select md5(prosrc) from pg_proc where oid='public.flag_payout_reversal_required(uuid,text,jsonb)'::regprocedure)
union all select 'a3_binding', (select 'args='||pg_get_function_identity_arguments(p.oid)||' | result='||pg_get_function_result(p.oid)||' | secdef='||p.prosecdef::text||' | cfg='||coalesce(array_to_string(p.proconfig,';'),'<none>') from pg_proc p where p.oid='public.record_payout_attempt_result(uuid,text,text,jsonb)'::regprocedure)
union all select 'a4_binding', (select 'args='||pg_get_function_identity_arguments(p.oid)||' | result='||pg_get_function_result(p.oid)||' | secdef='||p.prosecdef::text||' | cfg='||coalesce(array_to_string(p.proconfig,';'),'<none>') from pg_proc p where p.oid='public.flag_payout_reversal_required(uuid,text,jsonb)'::regprocedure)
union all select 'claim148_prosrc_md5', (select md5(prosrc) from pg_proc where oid='public.claim_payout_attempt(uuid,text,interval)'::regprocedure)
union all select 'notify148_prosrc_md5', (select md5(prosrc) from pg_proc where oid='public.notify_transfer_state_inbox()'::regprocedure)
union all select 'info_a3_acl', (select coalesce(proacl::text,'<default>')||' owner='||proowner::regrole::text from pg_proc where oid='public.record_payout_attempt_result(uuid,text,text,jsonb)'::regprocedure)
union all select 'info_a4_acl', (select coalesce(proacl::text,'<default>')||' owner='||proowner::regrole::text from pg_proc where oid='public.flag_payout_reversal_required(uuid,text,jsonb)'::regprocedure)
union all select 'info_payout_attempts', (select count(*)::text from public.payout_attempts)
union all select 'info_payout_decisions', (select count(*)::text from public.payout_decisions)
union all select 'info_seller_win_rows', (select count(*)::text from public.transfers where status='buyer_confirmed' and buyer_confirmed_at is null and dispute_resolution='resolved_seller_paid')
union all select 'info_dispute_resolutions', (select count(*)::text from public.dispute_resolutions)
union all select 'info_open_disputes', (select count(*)::text from public.transfers where disputed_at is not null and dispute_resolved_at is null)
